/*
 * TRYCLE | The code-breaking puzzle
 * Original Python game and puzzle: D.J. Carroll
 * Single-file p5.js adaptation of Trycle 10.0.
 *
 * RUN: Paste this entire file into sketch.js in https://editor.p5js.org/.
 * Uses the editor's standard p5.js library. No p5.sound, images, fonts,
 * sound uploads, preload(), or changes to index.html are required.
 * Original sounds (compressed to MP3) are embedded at the bottom of this file.
 *
 * SETTINGS: Edit the clearly labeled global settings block below.
 * Mouse/touch: click a region to toggle its bit. Click an outer rim to
 * magnify a puzzle. Escape closes a panel. M toggles audio.
 *
 * RULES PRESERVED:
 * - Outer targets are the Hamming encodings of 0 through 15.
 *   Their numbered identities stay fixed; their positions are shuffled.
 * - Center target is the encoding of 2; it unlocks after all 16 outers.
 * - Inner circles test even parity. The rim tests the EXACT target code.
 * - Solved puzzles lock. All randomized puzzles begin unsolved.
 * - Starting order and later shuffles are controlled by the settings below.
 * - Solve shuffles move only unsolved outer trycles; solved ones stay put.
 * - Penalty and timed shuffles move all outer trycles, including solved ones.
 * - The center never moves. Clicks are disabled during the quick slide.
 * - With at least FREEDOM_LIMIT solved, a move away from the target
 *   re-randomizes one solved puzzle. The center then locks again.
 * - Timer uses elapsed wall time, including background-tab time.
 *
 * Browser additions: replay, mute, instructions, optional magnification,
 * responsive canvas, and restart confirmation. No game data is transmitted.
 */

// ========================= GLOBAL SETTINGS =========================
const TIME_LIMIT = 30;               // Game length in minutes.
const FREEDOM_LIMIT = 5;             // Penalties start at this solved count.

const START_UNSHUFFLED = true;      // true = start clockwise 0-15; false = random.
const SHUFFLE_ON_SOLVE = true;       // Move UNSOLVED outer trycles only.
const SHUFFLE_ON_MISTAKE = true;     // Move ALL outer trycles after a penalty.
const SHUFFLE_ON_TIMER = true;       // Move ALL outer trycles every n seconds.
const SHUFFLE_INTERVAL_SECONDS = 3000; // n: time between automatic shuffles.

const ANIMATE_SHUFFLES = true;       // true = quick slide; false = instant.
const SHUFFLE_DURATION_MS = 350;     // Slide duration in milliseconds.
// All toggles are independent. Starting positions are set instantly.
// START_UNSHUFFLED changes positions only; the puzzle bits still randomize.
// Turning off mistake shuffling does NOT turn off the scramble penalty.
// Timed shuffles run only during play, including while help is open.
// Edit these values, then restart the sketch to apply your settings.
// ===================================================================
const BOARD_W = 1000;
const BOARD_H = 900;
const INK = '#eaf2f5';
const MUTED = '#91a2ad';
const GREEN = '#9be34d';
const RED = '#ff5d71';
const BG = '#080e14';
const BIT_NAMES = ['d1', 'd2', 'd3', 'd4', 'p1', 'p2', 'p3'];

let trycles = [];
let phase = 'welcome'; // welcome, setting, ready, playing, won, lost
let moves = 0;
let deadline = 0;
let secondsLeft = TIME_LIMIT * 60;
let stageStarted = 0;
let randomizedCount = 0;
let lastSecond = -1;
let panel = null; // help, restart, zoom
let zoomIndex = -1;
let buttons = [];
let viewScale = 1;
let viewX = 0;
let viewY = 0;
let pointer = { x: -1, y: -1 };
let notice = '';
let noticeUntil = 0;
let audioEnabled = true;
let audioContext = null;
let audioBuffers = {};
let audioLoading = false;
let activeSound = null;
let soundRequest = 0;
let canvasElement;
let shuffleAnimation = null;
let nextShuffleAt = 0;
let shuffleRevision = 0;

// Pure puzzle logic, independent of the rendering code.
class Trycle {
  constructor(decimal, x, y, radius, index) {
    this.index = index;
    this.x = x;
    this.y = y;
    this.r = radius;
    const d1 = decimal & 1;
    const d2 = (decimal >> 1) & 1;
    const d3 = (decimal >> 2) & 1;
    const d4 = (decimal >> 3) & 1;
    this.target = [d1, d2, d3, d4,
      d1 ^ d2 ^ d4, d1 ^ d3 ^ d4, d2 ^ d3 ^ d4];
    this.bits = this.target.slice();
    this.flashUntil = 0;
  }

  get solved() {
    return this.bits.every((bit, i) => bit === this.target[i]);
  }

  randomize() {
    do {
      this.bits = BIT_NAMES.map(() => Math.random() < 0.5 ? 0 : 1);
    } while (this.solved);
  }

  parity() {
    const [a, b, c, d, p, q, r] = this.bits;
    return [(a ^ c ^ d ^ q) === 0,
      (b ^ c ^ d ^ r) === 0, (a ^ b ^ d ^ p) === 0];
  }
}

function geometry(x, y, r) {
  const offset = r * 4 / 3;
  const low = Math.sqrt(3) * offset / 6;
  const high = Math.sqrt(3) * offset / 3;
  return {
    circles: [[x - offset / 2, y + low],
      [x + offset / 2, y + low], [x, y - high]],
    bits: [[x - offset / 4 - r / 6, y + (low - high) / 2 - r / 12],
      [x + offset / 4 + r / 6, y + (low - high) / 2 - r / 12],
      [x, y + low + r / 6], [x, y],
      [x, y - high - r / 4],
      [x - offset / 2 - r / 4, y + low + r / 4],
      [x + offset / 2 + r / 4, y + low + r / 4]],
    rim: r * 1.25 + high
  };
}

function hitBit(px, py, x, y, r) {
  const g = geometry(x, y, r);
  const membership = g.circles.reduce((mask, c, i) =>
    mask | ((Math.hypot(px - c[0], py - c[1]) < r) ? 1 << i : 0), 0);
  // Left=1, right=2, top=4. Each of the seven regions has one bit.
  return ({ 1: 5, 2: 6, 3: 2, 4: 4, 5: 0, 6: 1, 7: 3 })[membership] ?? -1;
}

function outerSolved() {
  return trycles.slice(0, 16).filter(t => t.solved).length;
}

function solvedCount() {
  return trycles.filter(t => t.solved).length;
}

function canEdit(index) {
  return phase === 'playing' && !shuffleAnimation && !trycles[index].solved &&
    (index < 16 || outerSolved() === 16);
}

function makeBoard() {
  shuffleAnimation = null;
  nextShuffleAt = 0;
  trycles = [];
  const add = (x, y) => {
    const i = trycles.length;
    trycles.push(new Trycle(i, x, y + 85, 35, i));
  };
  for (let i = 0; i < 6; i++) add(i * 1000 / 6 + 1000 / 12, 87.5);
  add(1000 * 11 / 12, 262.5);
  add(1000 * 11 / 12, 437.5);
  for (let i = 5; i >= 0; i--) add(i * 1000 / 6 + 1000 / 12, 612.5);
  add(1000 / 12, 437.5);
  add(1000 / 12, 262.5);
  trycles.push(new Trycle(2, 500, 435, 85, 16));
  if (!START_UNSHUFFLED) shuffleOuterTrycles(false, false);
}

function shuffleOuterTrycles(unsolvedOnly = false, animate = ANIMATE_SHUFFLES) {
  // Stable puzzle IDs and target bits never depend on a puzzle's location.
  // Keep solved positions out of the available slots for a solve shuffle.
  if (shuffleAnimation) return false;
  const outer = trycles.slice(0, 16).filter(t => !unsolvedOnly || !t.solved);
  if (outer.length < 2) return false; // One remaining trycle cannot swap alone.
  const positions = outer.map(t => ({ x: t.x, y: t.y }));
  // Sattolo's shuffle gives a random cycle: every selected trycle moves.
  for (let i = positions.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * i);
    [positions[i], positions[j]] = [positions[j], positions[i]];
  }
  const paths = outer.map((t, i) => ({
    index: t.index, fromX: t.x, fromY: t.y,
    toX: positions[i].x, toY: positions[i].y
  }));
  outer.forEach((t, i) => {
    t.x = positions[i].x;
    t.y = positions[i].y;
  });
  const duration = Number(SHUFFLE_DURATION_MS);
  if (animate && Number.isFinite(duration) && duration > 0) {
    shuffleAnimation = { startedAt: Date.now(), duration, paths };
  }
  shuffleRevision++;
  if (panel === 'zoom') panel = null;
  return true;
}

function updateShuffleAnimation(now = Date.now()) {
  if (shuffleAnimation && now - shuffleAnimation.startedAt >= shuffleAnimation.duration) {
    shuffleAnimation = null;
  }
}

function displayedPosition(t, now = Date.now()) {
  const path = shuffleAnimation && shuffleAnimation.paths.find(p => p.index === t.index);
  if (!path) return { x: t.x, y: t.y };
  const progress = Math.max(0, Math.min(1,
    (now - shuffleAnimation.startedAt) / shuffleAnimation.duration));
  const eased = progress * progress * (3 - 2 * progress); // Smooth, quick slide.
  return {
    x: path.fromX + (path.toX - path.fromX) * eased,
    y: path.fromY + (path.toY - path.fromY) * eased
  };
}

function shuffleIntervalMs() {
  const seconds = Number(SHUFFLE_INTERVAL_SECONDS);
  return Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : 30000;
}

function checkTimedShuffle(now) {
  if (!SHUFFLE_ON_TIMER || phase !== 'playing' || shuffleAnimation ||
      nextShuffleAt === 0 || now < nextShuffleAt) return;
  shuffleOuterTrycles(false);
  notifyPlayer('Timed shuffle. All outer trycles moved.');
  // Keep a cadence from the start of play. After a background-tab delay,
  // shuffle once, then skip missed intervals instead of replaying a burst.
  const interval = shuffleIntervalMs();
  nextShuffleAt += (Math.floor((now - nextShuffleAt) / interval) + 1) * interval;
}

function setup() {
  const cnv = createCanvas(windowWidth, windowHeight);
  canvasElement = cnv.elt;
  pixelDensity(Math.min(window.devicePixelRatio || 1, 2));
  textFont('sans-serif');
  document.body.style.margin = '0';
  document.body.style.background = BG;
  canvasElement.style.display = 'block';
  canvasElement.style.touchAction = 'none';
  canvasElement.setAttribute('tabindex', '0');
  canvasElement.setAttribute('aria-label', 'Trycle puzzle by D.J. Carroll. Click a binary region to toggle it. Click a rim to enlarge. M toggles sound.');
  // Pointer events handle mouse, pen and touch once, without synthesized clicks.
  canvasElement.addEventListener('pointerdown', event => {
    if (event.button !== 0) return;
    event.preventDefault();
    canvasElement.focus();
    updatePointer(event);
    unlockAudio();
    handlePointer(pointer.x, pointer.y);
  });
  canvasElement.addEventListener('pointermove', updatePointer);
  canvasElement.addEventListener('pointerleave', () => {
    pointer = { x: -1, y: -1 };
  });
  canvasElement.addEventListener('keydown', event => {
    if (event.key.toLowerCase() === 'm') toggleSound();
    if (event.key === 'Escape') panel = null;
  });
  makeBoard();
  fitBoard();
}

function fitBoard() {
  viewScale = Math.min(width / BOARD_W, height / BOARD_H);
  viewX = (width - BOARD_W * viewScale) / 2;
  viewY = (height - BOARD_H * viewScale) / 2;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  fitBoard();
}

function updatePointer(event) {
  const canvasBounds = canvasElement.getBoundingClientRect();
  pointer = {
    x: ((event.clientX - canvasBounds.left) * width / canvasBounds.width - viewX) / viewScale,
    y: ((event.clientY - canvasBounds.top) * height / canvasBounds.height - viewY) / viewScale
  };
}

function startGame() {
  stopSound();
  makeBoard();
  phase = 'setting';
  stageStarted = Date.now();
  randomizedCount = 0;
  moves = 0;
  secondsLeft = TIME_LIMIT * 60;
  lastSecond = -1;
  panel = null;
  zoomIndex = -1;
  notice = '';
}

function advanceGame() {
  const now = Date.now();
  updateShuffleAnimation(now);
  if (phase === 'setting') {
    const wanted = Math.min(17, Math.floor((now - stageStarted) / 120) + 1);
    while (randomizedCount < wanted) {
      trycles[randomizedCount++].randomize();
      playSound('safe_click');
    }
    if (randomizedCount === 17) {
      phase = 'ready';
      stageStarted = now;
    }
  } else if (phase === 'ready' && now - stageStarted >= 3000) {
    phase = 'playing';
    deadline = now + TIME_LIMIT * 60000;
    nextShuffleAt = now + shuffleIntervalMs();
    playSound('begin');
    lastSecond = TIME_LIMIT * 60;
  }
  if (phase === 'playing') {
    secondsLeft = Math.max(0, Math.ceil((deadline - now) / 1000));
    if (secondsLeft === 0) finishGame(false);
    else if (secondsLeft !== lastSecond) {
      lastSecond = secondsLeft;
      // Do not interrupt a success or penalty sound with the clock tick.
      if (!activeSound) playSound('clock');
    }
    checkTimedShuffle(now);
  }
}

function finishGame(won) {
  shuffleAnimation = null;
  nextShuffleAt = 0;
  phase = won ? 'won' : 'lost';
  panel = null;
  playSound(won ? 'win' : 'fail');
}

function toggleBit(index, bit) {
  const revision = shuffleRevision;
  advanceGame(); // Enforce timeout and timed shuffles even after backgrounding.
  if (revision !== shuffleRevision) return;
  if (!canEdit(index) || bit < 0 || bit > 6) return;
  const t = trycles[index];
  const countBefore = solvedCount();
  const movedAway = t.bits[bit] === t.target[bit];
  t.bits[bit] ^= 1;
  moves++;
  let penalized = false;
  if (countBefore >= FREEDOM_LIMIT && movedAway) {
    const solved = trycles.filter(tile => tile.solved);
    if (solved.length) {
      const reset = solved[Math.floor(Math.random() * solved.length)];
      reset.randomize();
      reset.flashUntil = Date.now() + 1800;
      notifyPlayer('Wrong direction. A solved trycle has been scrambled.');
      playSound('safe_click');
      penalized = true;
      if (panel === 'zoom') panel = null;
    }
  }
  if (!penalized) playSound(t.solved ? 'refresh' : 'crunch');
  if (t.solved) {
    notifyPlayer(index === 16 ? 'Code cracked!' :
      outerSolved() === 16 ? 'All outer trycles solved. The center is unlocked!' :
        'Trycle ' + index + ' solved.');
    if (panel === 'zoom') panel = null;
  }
  if (trycles.every(tile => tile.solved)) {
    finishGame(true);
    return;
  }
  if (penalized && SHUFFLE_ON_MISTAKE) {
    shuffleOuterTrycles(false);
    notifyPlayer('Wrong direction. One trycle scrambled; all outer trycles moved.');
  } else if (t.solved && index < 16 && SHUFFLE_ON_SOLVE) {
    if (shuffleOuterTrycles(true)) {
      notifyPlayer('Trycle ' + index + ' solved. Unsolved trycles moved.');
    }
  }
}

function notifyPlayer(message) {
  notice = message;
  noticeUntil = Date.now() + 4000;
}

function draw() {
  advanceGame();
  background(BG);
  fitBoard();
  push();
  translate(viewX, viewY);
  scale(viewScale);
  buttons = [];
  drawHeader();
  for (const t of trycles) {
    const tileDisplay = displayedPosition(t);
    drawTrycle(t, tileDisplay.x, tileDisplay.y, t.r);
  }
  drawStatus();
  if (phase === 'welcome') drawWelcome();
  if (phase === 'setting' || phase === 'ready') drawCountdown();
  if (phase === 'won' || phase === 'lost') drawResult();
  if (panel) drawPanel();
  pop();
  const overButton = buttons.some(b => contains(b, pointer.x, pointer.y));
  const overTile = phase === 'playing' && !shuffleAnimation && !panel && trycles.some(t =>
    !t.solved && Math.hypot(pointer.x - t.x, pointer.y - t.y) < geometry(t.x, t.y, t.r).rim);
  canvasElement.style.cursor = overButton || overTile || panel === 'zoom' ? 'pointer' : 'default';
}

function label(value, x, y, size = 16, colorValue = INK, align = CENTER) {
  noStroke();
  fill(colorValue);
  textSize(size);
  textAlign(align, CENTER);
  text(value, x, y);
}

function drawHeader() {
  label('TRYCLE', 28, 34, 30, INK, LEFT);
  label('THE CODE-BREAKING PUZZLE', 29, 63, 10, MUTED, LEFT);
  button('sound', audioEnabled ? 'Sound on' : 'Sound off', 636, 22, 110, 37);
  button('help', 'How to play', 756, 22, 120, 37);
  button('restart', 'New game', 886, 22, 92, 37);
  stroke('#24313b');
  strokeWeight(1);
  line(28, 85, 972, 85);
}

function drawTrycle(t, x, y, r, enlarged = false) {
  const g = geometry(x, y, r);
  const parity = t.parity();
  const beforePlay = phase === 'welcome' ||
    (phase === 'setting' && t.index >= randomizedCount);
  const editable = canEdit(t.index);
  const hovered = editable && (enlarged || !panel) ? hitBit(pointer.x, pointer.y, x, y, r) : -1;
  if (Date.now() < t.flashUntil) {
    noStroke();
    fill(255, 93, 113, 22 + 16 * Math.sin(Date.now() / 80));
    circle(x, y, g.rim * 2 + 12);
  }
  noFill();
  g.circles.forEach((c, i) => {
    stroke(parity[i] ? GREEN : RED);
    strokeWeight(enlarged ? 3 : 1.8);
    circle(c[0], c[1], r * 2);
  });
  stroke(beforePlay || t.solved ? GREEN : RED);
  strokeWeight(enlarged ? 5 : 4);
  circle(x, y, g.rim * 2);
  if (!beforePlay) {
    g.bits.forEach((p, i) => {
      if (hovered === i) {
        noStroke();
        fill('#354652');
        circle(p[0], p[1], Math.min(r * 0.47, 36));
      }
      label(String(t.bits[i]), p[0], p[1], r >= 80 ? 24 : 12,
        t.solved ? GREEN : INK);
    });
  }
  if (!enlarged) {
    const title = t.index === 16 ? (phase === 'playing' && outerSolved() === 16 ?
      'CENTER UNLOCKED' : 'CENTER') : String(t.index);
    label(t.solved && !beforePlay ? title + '  ✓' : title,
      x, y + g.rim + 16, t.index === 16 ? 11 : 10, t.solved ? GREEN : MUTED);
  }
}

function drawStatus() {
  const playing = ['playing', 'won', 'lost'].includes(phase);
  if (panel !== 'board') label(playing && outerSolved() < 16 ? 'Solve the 16 outer trycles to unlock the center.' :
    playing ? 'The center is yours. Crack the final code.' : '17 trycles. One code to crack.',
    500, 800, 15, MUTED);
  const sec = Math.ceil(secondsLeft);
  const clock = String(Math.floor(sec / 60)).padStart(2, '0') + ':' + String(sec % 60).padStart(2, '0');
  label(playing ? solvedCount() + ' / 17' : '0 / 17', 245, 858, 27, GREEN);
  label(clock, 500, 858, 30, secondsLeft <= 60 ? RED : INK);
  label(String(moves), 755, 858, 27);
  label('TRYCLES SOLVED', 245, 887, 10, MUTED);
  label('TIME REMAINING', 500, 887, 10, MUTED);
  label('MOVES', 755, 887, 10, MUTED);
  if (phase === 'playing') {
    const warning = Date.now() < noticeUntil ? notice :
      solvedCount() >= FREEDOM_LIMIT ? 'Careful: wrong-direction moves now scramble a solved trycle.' :
        'Click a region to flip 0 / 1. Click a rim to enlarge.';
    label(warning, 500, 825, 13, Date.now() < noticeUntil ? INK : MUTED);
  }
}

function button(id, title, x, y, w, h, primary = false) {
  const b = { id, x, y, w, h };
  buttons.push(b);
  const hover = contains(b, pointer.x, pointer.y);
  stroke(primary ? GREEN : '#384651');
  strokeWeight(1);
  fill(primary ? (hover ? '#b4f16e' : GREEN) : (hover ? '#283945' : '#15212b'));
  rect(x, y, w, h, 8);
  label(title, x + w / 2, y + h / 2, 13, primary ? BG : INK);
}

function contains(b, x, y) {
  return x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
}

function modal(y = 225, h = 390) {
  // Only panel controls may receive clicks while an overlay is open.
  buttons = [];
  noStroke();
  fill(3, 8, 13, 224);
  rect(0, 0, BOARD_W, BOARD_H);
  stroke('#35434e');
  strokeWeight(1);
  fill('#101b24');
  rect(165, y, 670, h, 18);
}

function drawWelcome() {
  modal(230, 380);
  label('TRYCLE', 500, 296, 52);
  label('A puzzle by D.J. Carroll', 500, 341, 16, MUTED);
  label('Flip the bits. Read the circles. Crack the code.', 500, 394, 19);
  label('16 outer trycles  /  1 final center  /  ' + TIME_LIMIT + ' minutes', 500, 431, 15, MUTED);
  button('start', 'Set the code', 365, 474, 270, 48, true);
  button('help', 'How to play', 415, 541, 170, 36);
}

function drawCountdown() {
  modal(300, 235);
  label(phase === 'setting' ? 'Setting the code...' : 'The code is set.', 500, 360, 30);
  label(phase === 'setting' ? randomizedCount + ' / 17 trycles scrambled' :
    'Ready in ' + Math.max(1, 3 - Math.floor((Date.now() - stageStarted) / 1000)),
    500, 418, 23, GREEN);
  label('You have ' + TIME_LIMIT + ' minutes.', 500, 478, 16, MUTED);
}

function drawResult() {
  modal(220, 420);
  const won = phase === 'won';
  label(won ? 'Code cracked!' : 'Time is up.', 500, 287, 44, won ? GREEN : RED);
  label(solvedCount() + ' / 17 trycles solved  ·  ' + moves + ' moves', 500, 341, 18);
  if (won) {
    label('You just built Hamming codes.', 500, 403, 23);
    label('Each circle checks even parity. Together, the checks can', 500, 443, 16, MUTED);
    label('locate a single-bit error so a computer can correct it.', 500, 470, 16, MUTED);
  } else {
    label('A fresh code is another chance to find the pattern.', 500, 424, 18, MUTED);
  }
  button('start', 'Play again', 365, 535, 270, 48, true);
  button('view', 'View the board', 415, 594, 170, 30);
}

function drawPanel() {
  if (panel === 'board') {
    // drawResult was drawn earlier; redraw the board for end-game inspection.
    noStroke(); fill(BG); rect(0, 0, BOARD_W, BOARD_H);
    buttons = [];
    drawHeader();
    for (const t of trycles) drawTrycle(t, t.x, t.y, t.r);
    drawStatus();
    button('close', 'Back to results', 405, 802, 190, 32);
    return;
  }
  if (panel === 'zoom') {
    modal(145, 565);
    const t = trycles[zoomIndex];
    label(t.index === 16 ? 'Center trycle' : 'Trycle ' + t.index, 500, 188, 23);
    drawTrycle(t, 500, 430, 92, true);
    label('Click a region to flip its bit. The timer keeps running.', 500, 653, 15, MUTED);
    button('close', 'Close', 714, 168, 90, 35);
  } else if (panel === 'help') {
    modal(150, 580);
    label('How to play', 500, 198, 32);
    const lines = [
      'Click any of the seven regions to switch its 0 or 1.',
      'The three inner circles give clues as you change the bits.',
      'A green outer rim means that trycle matches its secret code.',
      'Solved trycles lock. Solve all 16 to unlock the center.',
      'At ' + FREEDOM_LIMIT + ' solved, a wrong-direction move scrambles one solved trycle.',
      '',
      SHUFFLE_ON_SOLVE ? 'On a solve: unsolved trycles move; solved trycles stay put.' :
        'On a solve: positions stay fixed.',
      SHUFFLE_ON_MISTAKE ? 'On a penalty: all outer trycles move.' :
        'On a penalty: positions stay fixed.',
      SHUFFLE_ON_TIMER ? 'Every ' + (shuffleIntervalMs() / 1000) + ' seconds: all outer trycles move.' :
        'Timed shuffling is off.',
      ANIMATE_SHUFFLES ? 'Trycles slide quickly. Wait for them to stop before clicking.' :
        'Trycles switch positions instantly.',
      '',
      'Click a rim to enlarge. M toggles sound. The center never moves.',
      'The timer continues while panels are open.'
    ];
    lines.forEach((s, i) => label(s, 500, 254 + i * 29, 15, i >= 6 && i <= 9 ? GREEN : INK));
    button('close', 'Got it', 410, 663, 180, 42, true);
  } else if (panel === 'restart') {
    modal(290, 260);
    label('Start a new game?', 500, 349, 30);
    label('This will replace your current code and reset the timer.', 500, 399, 16, MUTED);
    button('close', 'Keep playing', 300, 460, 185, 44);
    button('start', 'New game', 515, 460, 185, 44, true);
  }
}

function handlePointer(x, y) {
  const revision = shuffleRevision;
  advanceGame();
  if (revision !== shuffleRevision) return; // Do not hit a newly moved, unseen tile.
  const b = buttons.slice().reverse().find(item => contains(item, x, y));
  if (b) {
    if (b.id === 'sound') toggleSound();
    if (b.id === 'start') startGame();
    if (b.id === 'help') panel = 'help';
    if (b.id === 'restart') panel = 'restart';
    if (b.id === 'close') panel = null;
    if (b.id === 'view') panel = 'board';
    return;
  }
  if (panel === 'zoom') {
    toggleBit(zoomIndex, hitBit(x, y, 500, 430, 92));
    return;
  }
  if (panel || phase !== 'playing') return;
  for (const t of trycles) {
    if (!canEdit(t.index)) continue;
    const bit = hitBit(x, y, t.x, t.y, t.r);
    if (bit >= 0) {
      toggleBit(t.index, bit);
      return;
    }
    if (Math.hypot(x - t.x, y - t.y) <= geometry(t.x, t.y, t.r).rim + 4) {
      zoomIndex = t.index;
      panel = 'zoom';
      return;
    }
  }
}

// Native Web Audio avoids requiring the separate p5.sound library.
// Decode only after a user gesture; audio failures never block the puzzle.
function unlockAudio() {
  if (!audioEnabled) return;
  try {
    const AudioClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioClass) return;
    if (!audioContext) audioContext = new AudioClass();
    if (audioContext.state === 'suspended') audioContext.resume().catch(() => {});
    if (!audioLoading) {
      audioLoading = true;
      for (const [name, base64] of Object.entries(TRYCLE_AUDIO)) {
        const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
        audioBuffers[name] = audioContext.decodeAudioData(bytes.buffer).catch(() => null);
      }
    }
  } catch (_) { /* Silent play is still available. */ }
}

function stopSound() {
  soundRequest++;
  if (activeSound) {
    try { activeSound.stop(); } catch (_) { /* Already ended. */ }
    activeSound = null;
  }
}

async function playSound(name) {
  if (!audioEnabled || !audioContext || !audioBuffers[name]) return;
  stopSound();
  const request = soundRequest;
  const buffer = await audioBuffers[name];
  if (!buffer || !audioEnabled || request !== soundRequest) return;
  try {
    const source = audioContext.createBufferSource();
    const gain = audioContext.createGain();
    source.buffer = buffer;
    gain.gain.value = name === 'clock' ? 0.16 : 0.65;
    source.connect(gain);
    gain.connect(audioContext.destination);
    source.onended = () => {
      source.disconnect(); gain.disconnect();
      if (activeSound === source) activeSound = null;
    };
    activeSound = source;
    source.start();
  } catch (_) { /* Continue gameplay if audio is unavailable. */ }
}

function toggleSound() {
  audioEnabled = !audioEnabled;
  if (!audioEnabled) stopSound();
  else unlockAudio();
}

// Original audio assets from Trycle 10.0, embedded to keep this self-contained.
// You can collapse this object in your editor; gameplay code is all above.
const TRYCLE_AUDIO = {
  "begin": "",
  "clock": "",
  "crunch": "",
  "fail": "",
  "refresh": "",
  "safe_click": "",
  "win": ""
};
